278:     /**
279:      * Check whether the given hint option matches the table qualified names. For convenience, we
280:      * follow a simple rule: the matching is successful if the option is the suffix of the table
281:      * qualified names.
282:      */
283:     private boolean matchIdentifier(String option, String tableIdentifier) {
284:         String[] optionNames = option.split("\\.");
285:         int optionNameLength = optionNames.length;
286: 
287:         String[] tableNames = tableIdentifier.split("\\.");
288:         int tableNameLength = tableNames.length;
289: 
290:         for (int i = 0; i < Math.min(optionNameLength, tableNameLength); i++) {
291:             String currOptionName = optionNames[optionNameLength - 1 - i];
292:             String currTableName = tableNames[tableNameLength - 1 - i];
293: 
294:             if (!currOptionName.equals(currTableName)) {
295:                 return false;
296:             }
297:         }
298: 
299:         return true;
300:     }
