322:     private void updateInfoForOptionCheck(String hintName, Optional<String> tableName) {
323:         if (tableName.isPresent()) {
324:             Map<String, Boolean> optionMapper = allOptionsInJoinHints.get(hintName);
325:             for (String option : optionMapper.keySet()) {
326:                 if (matchIdentifier(option, tableName.get())) {
327:                     // if the hint has not been checked before, update it
328:                     allOptionsInJoinHints.get(hintName).put(option, true);
329:                 }
330:             }
331:         }
332:     }
