66: 
67:     /** proposed leader, which has been notified of leadership grant, but has not confirmed. */
68:     private EmbeddedLeaderElection currentLeaderProposed;
69: 
70:     /** actual leader that has confirmed leadership and of which listeners have been notified. */
71:     private EmbeddedLeaderElection currentLeaderConfirmed;
72: 
73:     /** fencing UID for the current leader (or proposed leader). */
74:     private volatile UUID currentLeaderSessionId;
75: 
76:     /** the cached address of the current leader. */
77:     private String currentLeaderAddress;
78: 
79:     /** flag marking the service as terminated. */
80:     private boolean shutdown;
81: 
82:     // ------------------------------------------------------------------------
83: 
84:     public EmbeddedLeaderService(Executor notificationsDispatcher) {
85:         this.notificationExecutor = checkNotNull(notificationsDispatcher);
86:         this.allLeaderContenders = new HashSet<>();
87:         this.listeners = new HashSet<>();
88:     }
89: 
90:     // ------------------------------------------------------------------------
91:     //  shutdown and errors
92:     // ------------------------------------------------------------------------
93: 
94:     /**
95:      * Shuts down this leader election service.
96:      *
97:      * <p>This method does not perform a clean revocation of the leader status and no notification
98:      * to any leader listeners. It simply notifies all contenders and listeners that the service is
99:      * no longer available.
100:      */
101:     public void shutdown() {
102:         synchronized (lock) {
103:             shutdownInternally(new Exception("Leader election service is shutting down"));
104:         }
105:     }
106: 
107:     @VisibleForTesting
108:     public boolean isShutdown() {
109:         synchronized (lock) {
110:             return shutdown;
111:         }
112:     }
113: 
114:     private void fatalError(Throwable error) {
115:         LOG.error(
116:                 "Embedded leader election service encountered a fatal error. Shutting down service.",
117:                 error);
118: 
119:         synchronized (lock) {
120:             shutdownInternally(
121:                     new Exception(
122:                             "Leader election service is shutting down after a fatal error", error));
123:         }
124:     }
125: 
126:     @GuardedBy("lock")
127:     private void shutdownInternally(Exception exceptionForHandlers) {
128:         Preconditions.checkState(Thread.holdsLock(lock));
129: 
130:         if (!shutdown) {
131:             // clear all leader status
132:             currentLeaderProposed = null;
133:             currentLeaderConfirmed = null;
134:             currentLeaderSessionId = null;
135:             currentLeaderAddress = null;
136: 
137:             // fail all registered listeners
138:             for (EmbeddedLeaderElection leaderElection : allLeaderContenders) {
139:                 leaderElection.shutdown(exceptionForHandlers);
140:             }
141:             allLeaderContenders.clear();
142: 
143:             // fail all registered listeners
144:             for (EmbeddedLeaderRetrievalService service : listeners) {
145:                 service.shutdown(exceptionForHandlers);
146:             }
147:             listeners.clear();
148: 
149:             shutdown = true;
150:         }
151:     }
152: 
153:     // ------------------------------------------------------------------------
154:     //  creating contenders and listeners
155:     // ------------------------------------------------------------------------
156: 
157:     public LeaderElection createLeaderElectionService(String componentId) {
158:         checkState(!shutdown, "leader election service is shut down");
159:         return new EmbeddedLeaderElection(componentId);
160:     }
161: 
162:     public LeaderRetrievalService createLeaderRetrievalService() {
163:         checkState(!shutdown, "leader election service is shut down");
164:         return new EmbeddedLeaderRetrievalService();
165:     }
166: 
167:     // ------------------------------------------------------------------------
168:     //  adding and removing contenders & listeners
169:     // ------------------------------------------------------------------------
170: 
171:     /** Callback from leader contenders when they start their service. */
172:     private void addContender(
173:             EmbeddedLeaderElection embeddedLeaderElection, LeaderContender contender) {
174:         synchronized (lock) {
175:             checkState(!shutdown, "leader election is shut down");
176:             checkState(!embeddedLeaderElection.running, "leader election is already started");
177: 
178:             try {
179:                 if (!allLeaderContenders.add(embeddedLeaderElection)) {
180:                     throw new IllegalStateException(
181:                             "leader election was added to this service multiple times");
182:                 }
183: 
184:                 embeddedLeaderElection.contender = contender;
185:                 embeddedLeaderElection.running = true;
186: 
187:                 updateLeader()
188:                         .whenComplete(
189:                                 (aVoid, throwable) -> {
190:                                     if (throwable != null) {
191:                                         fatalError(throwable);
192:                                     }
193:                                 });
194:             } catch (Throwable t) {
195:                 fatalError(t);
196:             }
197:         }
198:     }
199: 
200:     /** Callback from leader contenders when they stop their service. */
201:     private void removeContender(EmbeddedLeaderElection embeddedLeaderElection) {
202:         synchronized (lock) {
203:             // if the leader election was not even started, simply do nothing
204:             if (!embeddedLeaderElection.running || shutdown) {
205:                 return;
206:             }
207: 
208:             try {
209:                 if (!allLeaderContenders.remove(embeddedLeaderElection)) {
210:                     throw new IllegalStateException(
211:                             "leader election does not belong to this service");
212:                 }
213: 
214:                 // stop the service
215:                 if (embeddedLeaderElection.isLeader) {
216:                     embeddedLeaderElection.contender.revokeLeadership();
217:                 }
218:                 embeddedLeaderElection.contender = null;
219:                 embeddedLeaderElection.running = false;
220:                 embeddedLeaderElection.isLeader = false;
221: 
222:                 // if that was the current leader, unset its status
223:                 if (currentLeaderConfirmed == embeddedLeaderElection) {
224:                     currentLeaderConfirmed = null;
225:                     currentLeaderSessionId = null;
226:                     currentLeaderAddress = null;
227:                 }
228:                 if (currentLeaderProposed == embeddedLeaderElection) {
229:                     currentLeaderProposed = null;
230:                     currentLeaderSessionId = null;
231:                 }
232: 
233:                 updateLeader()
234:                         .whenComplete(
235:                                 (aVoid, throwable) -> {
236:                                     if (throwable != null) {
237:                                         fatalError(throwable);
238:                                     }
239:                                 });
240:             } catch (Throwable t) {
241:                 fatalError(t);
242:             }
243:         }
244:     }
245: 
246:     /** Callback from leader contenders when they confirm a leader grant. */
247:     private void confirmLeader(
248:             final EmbeddedLeaderElection embeddedLeaderElection,
249:             final UUID leaderSessionId,
250:             final String leaderAddress) {
251:         synchronized (lock) {
252:             // if the leader election was shut down in the meantime, ignore this confirmation
253:             if (!embeddedLeaderElection.running || shutdown) {
254:                 return;
255:             }
256: 
257:             try {
258:                 // check if the confirmation is for the same grant, or whether it is a stale grant
259:                 if (embeddedLeaderElection == currentLeaderProposed
260:                         && currentLeaderSessionId.equals(leaderSessionId)) {
261:                     LOG.info(
262:                             "Received confirmation of leadership for leader {} , session={}",
263:                             leaderAddress,
264:                             leaderSessionId);
265: 
266:                     // mark leadership
267:                     currentLeaderConfirmed = embeddedLeaderElection;
268:                     currentLeaderAddress = leaderAddress;
269:                     currentLeaderProposed = null;
270: 
271:                     // notify all listeners
272:                     notifyAllListeners(leaderAddress, leaderSessionId);
273:                 } else {
274:                     LOG.debug(
275:                             "Received confirmation of leadership for a stale leadership grant. Ignoring.");
276:                 }
277:             } catch (Throwable t) {
278:                 fatalError(t);
279:             }
280:         }
281:     }
282: 
283:     private CompletableFuture<Void> notifyAllListeners(String address, UUID leaderSessionId) {
284:         final List<CompletableFuture<Void>> notifyListenerFutures =
285:                 new ArrayList<>(listeners.size());
286: 
287:         for (EmbeddedLeaderRetrievalService listener : listeners) {
288:             notifyListenerFutures.add(notifyListener(address, leaderSessionId, listener.listener));
289:         }
290: 
291:         return FutureUtils.waitForAll(notifyListenerFutures);
292:     }
293: 
294:     @GuardedBy("lock")
295:     private CompletableFuture<Void> updateLeader() {
296:         // this must be called under the lock
297:         Preconditions.checkState(Thread.holdsLock(lock));
298: 
299:         if (currentLeaderConfirmed == null && currentLeaderProposed == null) {
300:             // we need a new leader
301:             if (allLeaderContenders.isEmpty()) {
302:                 // no new leader available, tell everyone that there is no leader currently
303:                 return notifyAllListeners(null, null);
304:             } else {
305:                 // propose a leader and ask it
306:                 final UUID leaderSessionId = UUID.randomUUID();
307:                 EmbeddedLeaderElection embeddedLeaderElection =
308:                         allLeaderContenders.iterator().next();
309: 
310:                 currentLeaderSessionId = leaderSessionId;
311:                 currentLeaderProposed = embeddedLeaderElection;
312:                 currentLeaderProposed.isLeader = true;
313: 
314:                 LOG.info(
315:                         "Proposing leadership to the contender that is registered under component ID '{}'.",
316:                         embeddedLeaderElection.componentId);
317: 
318:                 return execute(
319:                         new GrantLeadershipCall(
320:                                 embeddedLeaderElection.contender, leaderSessionId, LOG));
321:             }
322:         } else {
323:             return CompletableFuture.completedFuture(null);
324:         }
325:     }
326: 
327:     private CompletableFuture<Void> notifyListener(
328:             @Nullable String address,
329:             @Nullable UUID leaderSessionId,
330:             LeaderRetrievalListener listener) {
331:         return CompletableFuture.runAsync(
332:                 new NotifyOfLeaderCall(address, leaderSessionId, listener, LOG),
333:                 notificationExecutor);
334:     }
335: 
336:     private void addListener(
337:             EmbeddedLeaderRetrievalService service, LeaderRetrievalListener listener) {
338:         synchronized (lock) {
339:             checkState(!shutdown, "leader election service is shut down");
340:             checkState(!service.running, "leader retrieval service is already started");
341: 
342:             try {
343:                 if (!listeners.add(service)) {
344:                     throw new IllegalStateException(
345:                             "leader retrieval service was added to this service multiple times");
346:                 }
347: 
348:                 service.listener = listener;
349:                 service.running = true;
350: 
351:                 // if we already have a leader, immediately notify this new listener
352:                 if (currentLeaderConfirmed != null) {
353:                     notifyListener(currentLeaderAddress, currentLeaderSessionId, listener);
354:                 }
355:             } catch (Throwable t) {
356:                 fatalError(t);
357:             }
358:         }
359:     }
360: 
361:     private void removeListener(EmbeddedLeaderRetrievalService service) {
362:         synchronized (lock) {
363:             // if the service was not even started, simply do nothing
364:             if (!service.running || shutdown) {
365:                 return;
366:             }
367: 
368:             try {
369:                 if (!listeners.remove(service)) {
370:                     throw new IllegalStateException(
371:                             "leader retrieval service does not belong to this service");
372:                 }
373: 
374:                 // stop the service
375:                 service.listener = null;
376:                 service.running = false;
377:             } catch (Throwable t) {
378:                 fatalError(t);
379:             }
380:         }
381:     }
382: 
383:     @VisibleForTesting
384:     CompletableFuture<Void> grantLeadership() {
385:         synchronized (lock) {
386:             if (shutdown) {
387:                 return getShutDownFuture();
388:             }
389: 
390:             return updateLeader();
391:         }
392:     }
393: 
394:     private CompletableFuture<Void> getShutDownFuture() {
395:         return FutureUtils.completedExceptionally(
396:                 new FlinkException("EmbeddedLeaderService has been shut down."));
397:     }
398: 
399:     @VisibleForTesting
400:     CompletableFuture<Void> revokeLeadership() {
401:         synchronized (lock) {
402:             if (shutdown) {
403:                 return getShutDownFuture();
404:             }
405: 
406:             if (currentLeaderProposed != null || currentLeaderConfirmed != null) {
407:                 final EmbeddedLeaderElection embeddedLeaderElection;
408: 
409:                 if (currentLeaderConfirmed != null) {
410:                     embeddedLeaderElection = currentLeaderConfirmed;
411:                 } else {
412:                     embeddedLeaderElection = currentLeaderProposed;
413:                 }
414: 
415:                 LOG.info("Revoking leadership of {}.", embeddedLeaderElection.contender);
416:                 embeddedLeaderElection.isLeader = false;
417:                 CompletableFuture<Void> revokeLeadershipCallFuture =
418:                         execute(new RevokeLeadershipCall(embeddedLeaderElection.contender));
419: 
420:                 CompletableFuture<Void> notifyAllListenersFuture = notifyAllListeners(null, null);
421: 
422:                 currentLeaderProposed = null;
423:                 currentLeaderConfirmed = null;
424:                 currentLeaderAddress = null;
425:                 currentLeaderSessionId = null;
426: 
427:                 return CompletableFuture.allOf(
428:                         revokeLeadershipCallFuture, notifyAllListenersFuture);
429:             } else {
430:                 return CompletableFuture.completedFuture(null);
431:             }
432:         }
433:     }
434: 
435:     private CompletableFuture<Void> execute(Runnable runnable) {
436:         return CompletableFuture.runAsync(runnable, notificationExecutor);
437:     }
