439:     // ------------------------------------------------------------------------
440:     //  election and retrieval service implementations
441:     // ------------------------------------------------------------------------
442: 
443:     private class EmbeddedLeaderElection implements LeaderElection {
444: 
445:         final String componentId;
446:         volatile LeaderContender contender;
447: 
448:         volatile boolean isLeader;
449: 
450:         volatile boolean running;
451: 
452:         EmbeddedLeaderElection(String componentId) {
453:             this.componentId = componentId;
454:         }
455: 
456:         @Override
457:         public void startLeaderElection(LeaderContender contender) throws Exception {
458:             checkNotNull(contender);
459:             addContender(this, contender);
460:         }
461: 
462:         @Override
463:         public void close() {
464:             removeContender(this);
465:         }
466: 
467:         @Override
468:         public void confirmLeadership(UUID leaderSessionID, String leaderAddress) {
469:             checkNotNull(leaderSessionID);
470:             checkNotNull(leaderAddress);
471:             confirmLeader(this, leaderSessionID, leaderAddress);
472:         }
473: 
474:         @Override
475:         public boolean hasLeadership(UUID leaderSessionId) {
476:             return isLeader && leaderSessionId.equals(currentLeaderSessionId);
477:         }
478: 
479:         void shutdown(Exception cause) {
480:             if (running) {
481:                 running = false;
482:                 isLeader = false;
483:                 contender.revokeLeadership();
484:                 contender = null;
485:             }
486:         }
487:     }
488: 
489:     // ------------------------------------------------------------------------
490: 
491:     private class EmbeddedLeaderRetrievalService implements LeaderRetrievalService {
492: 
493:         volatile LeaderRetrievalListener listener;
494: 
495:         volatile boolean running;
496: 
497:         @Override
498:         public void start(LeaderRetrievalListener listener) throws Exception {
499:             checkNotNull(listener);
500:             addListener(this, listener);
501:         }
502: 
503:         @Override
504:         public void stop() throws Exception {
505:             removeListener(this);
506:         }
507: 
508:         public void shutdown(Exception cause) {
509:             if (running) {
510:                 running = false;
511:                 listener = null;
512:             }
513:         }
514:     }
515: 
516:     // ------------------------------------------------------------------------
517:     //  asynchronous notifications
518:     // ------------------------------------------------------------------------
519: 
520:     private static class NotifyOfLeaderCall implements Runnable {
521: 
522:         @Nullable private final String address; // null if leader revoked without new leader
523:         @Nullable private final UUID leaderSessionId; // null if leader revoked without new leader
524: 
525:         private final LeaderRetrievalListener listener;
526:         private final Logger logger;
527: 
528:         NotifyOfLeaderCall(
529:                 @Nullable String address,
530:                 @Nullable UUID leaderSessionId,
531:                 LeaderRetrievalListener listener,
532:                 Logger logger) {
533: 
534:             this.address = address;
535:             this.leaderSessionId = leaderSessionId;
536:             this.listener = checkNotNull(listener);
537:             this.logger = checkNotNull(logger);
538:         }
539: 
540:         @Override
541:         public void run() {
542:             try {
543:                 listener.notifyLeaderAddress(address, leaderSessionId);
544:             } catch (Throwable t) {
545:                 logger.warn("Error notifying leader listener about new leader", t);
546:                 listener.handleError(t instanceof Exception ? (Exception) t : new Exception(t));
547:             }
548:         }
549:     }
550: 
551:     // ------------------------------------------------------------------------
552: 
553:     private static class GrantLeadershipCall implements Runnable {
554: 
555:         private final LeaderContender contender;
556:         private final UUID leaderSessionId;
557:         private final Logger logger;
558: 
559:         GrantLeadershipCall(LeaderContender contender, UUID leaderSessionId, Logger logger) {
560: 
561:             this.contender = checkNotNull(contender);
562:             this.leaderSessionId = checkNotNull(leaderSessionId);
563:             this.logger = checkNotNull(logger);
564:         }
565: 
566:         @Override
567:         public void run() {
568:             try {
569:                 contender.grantLeadership(leaderSessionId);
570:             } catch (Throwable t) {
571:                 logger.warn("Error granting leadership to contender", t);
572:                 contender.handleError(t instanceof Exception ? (Exception) t : new Exception(t));
573:             }
574:         }
575:     }
576: 
577:     private static class RevokeLeadershipCall implements Runnable {
578: 
579:         @Nonnull private final LeaderContender contender;
580: 
581:         RevokeLeadershipCall(@Nonnull LeaderContender contender) {
582:             this.contender = contender;
583:         }
584: 
585:         @Override
586:         public void run() {
587:             contender.revokeLeadership();
588:         }
589:     }
590: }
