463:     private static class TestingRescaleManagerContext implements RescaleManager.Context {
464: 
465:         // default configuration values to allow for easy transitioning between the phases
466:         private static final Duration SCALING_MIN = Duration.ofHours(1);
467:         private static final Duration SCALING_MAX = Duration.ofHours(2);
