495:             this.hasSufficientResources = false;
496:             this.hasDesiredResources = false;
497:         }
498: 
499:         public TestingRescaleManagerContext withDesiredRescaling() {
500:             // having desired resources should also mean that the sufficient resources are met
501:             this.hasSufficientResources = true;
502:             this.hasDesiredResources = true;
503: 
504:             return this;
505:         }
