514:         // ///////////////////////////////////////////////
515:         // RescaleManager.Context interface methods
516:         // ///////////////////////////////////////////////
517: 
518:         @Override
519:         public boolean hasSufficientResources() {
520:             return this.hasSufficientResources;
521:         }
522: 
523:         @Override
524:         public boolean hasDesiredResources() {
525:             return this.hasDesiredResources;
526:         }
