528:         @Override
529:         public void rescale() {
530:             rescaleTriggered.set(true);
531:         }
532: 
533:         @Override
534:         public void scheduleOperation(Runnable callback, Duration delay) {
535:             final Instant triggerTime =
536:                     Objects.requireNonNull(initializationTime).plus(elapsedTime).plus(delay);
537:             if (!scheduledTasks.containsKey(triggerTime)) {
538:                 scheduledTasks.put(triggerTime, new ArrayList<>());
539:             }
540: 
541:             scheduledTasks.get(triggerTime).add(callback);
542:         }
