572:         /**
573:          * Initializes the test instance and sets the context's elapsed time based on the passed
574:          * callback.
575:          */
576:         private DefaultRescaleManager createTestInstance(Runnable timeTransitioning) {
577:             final DefaultRescaleManager testInstance =
578:                     new DefaultRescaleManager(
579:                             initializationTime,
580:                             // clock that returns the time based on the configured elapsedTime
581:                             () -> Objects.requireNonNull(initializationTime).plus(elapsedTime),
582:                             this,
583:                             SCALING_MIN,
584:                             SCALING_MAX,
585:                             Duration.ofHours(5)) {
586:                         @Override
587:                         public void onChange() {
588:                             super.onChange();
589: 
590:                             // hack to avoid calling this method in every test method
591:                             // we want to trigger tasks that are meant to run right-away
592:                             TestingRescaleManagerContext.this.triggerOutdatedTasks();
593:                         }
