613:         /**
614:          * Transitions the context's time to a moment that falls into the test instance's cooldown
615:          * phase.
616:          */
617:         public void transitionIntoCooldownTimeframe() {
618:             this.elapsedTime = SCALING_MIN.dividedBy(2);
619:             this.triggerOutdatedTasks();
620:         }
