647:         private void triggerOutdatedTasks() {
648:             while (!scheduledTasks.isEmpty()) {
649:                 final Instant timeOfExecution = scheduledTasks.firstKey();
650:                 if (!timeOfExecution.isAfter(
651:                         Objects.requireNonNull(initializationTime).plus(elapsedTime))) {
652:                     scheduledTasks.remove(timeOfExecution).forEach(Runnable::run);
653:                 } else {
654:                     break;
655:                 }
656:             }
